1	namespace Maxx.Domain.Ranking;
2	
3	// As quatro visões do ranking (produto.md 5): escopo geral ou por curso, período semestre
4	// letivo ou histórico.
5	public enum EscopoDoRanking
6	{
7	    Geral,
8	    Curso,
9	}
10	
11	public enum PeriodoDoRanking
12	{
13	    Semestre,
14	    Historico,
15	}
16	
17	// Um aluno com conta, como o ranking o vê: o curso atual, porque quem troca de curso leva
18	// os pontos para o ranking do curso novo, e se já é ex-aluno.
19	public sealed record AlunoDoRanking(Guid Id, Guid CursoId, bool ExAluno);
20	
21	// Uma visão: o semestre só no período semestre, o curso só no escopo curso.
22	public sealed record VisaoDoRanking(EscopoDoRanking Escopo, PeriodoDoRanking Periodo, Guid? SemestreLetivoId, Guid? CursoId);
23	
24	// Uma linha de uma visão: a posição, os pontos e o instante de desempate, que a tabela
25	// guarda como coluna (ADR 0005).
26	public sealed record LinhaDoRanking(VisaoDoRanking Visao, Guid AlunoId, int Posicao, int Pontos, DateTimeOffset UltimaConcessaoEm);
27	
28	// O cálculo das visões a partir das parcelas. Regras (produto.md 5):
29	// - pontos são a soma das parcelas do aluno no período da visão;
30	// - aluno sem pontos na visão não tem linha nela;
31	// - desempate pelo instante da última concessão que compõe a pontuação: quem parou de
32	//   pontuar antes fica na frente; persistindo o empate, o id do aluno, para a posição não
33	//   oscilar entre dois recálculos;
34	// - ex-aluno só no histórico;
35	// - o escopo curso é o curso atual do aluno.
36	public static class Classificacao
37	{
38	    // O histórico, geral e por curso.
39	    public static IReadOnlyList<LinhaDoRanking> Historico(
40	        IEnumerable<AlunoDoRanking> alunos, IEnumerable<ParcelaDoRanking> parcelas)
41	    {
42	        ArgumentNullException.ThrowIfNull(alunos);
43	        ArgumentNullException.ThrowIfNull(parcelas);
44	
45	        return Visoes(alunos.ToList(), parcelas, PeriodoDoRanking.Historico, semestreLetivoId: null);
46	    }
47	
48	    // Um semestre letivo, geral e por curso: só as parcelas que contam nele e só alunos que
49	    // não são ex-alunos.
50	    public static IReadOnlyList<LinhaDoRanking> Semestre(
51	        Guid semestreLetivoId, IEnumerable<AlunoDoRanking> alunos, IEnumerable<ParcelaDoRanking> parcelas)
52	    {
53	        ArgumentNullException.ThrowIfNull(alunos);
54	        ArgumentNullException.ThrowIfNull(parcelas);
55	
56	        return Visoes(
